6	import { ActionButton } from "@/ui/action-button";
7	
8	type PhotoCaptureProps = {
9	  /** `null` while the current permission status is still being read. */
10	  permission: PermissionResponse | null;
11	  photoUri?: string;
12	  onRequestPermission: () => void;
13	  onOpenSettings: () => void;
14	  onCapture: (uri: string) => void;
15	  onClear: () => void;
16	};
17	
18	/**
19	 * The add-card screen's optional photo. Branches on every camera-permission
20	 * state — still resolving, granted, deniable, and permanently denied — and
21	 * only ever asks for the permission when the learner taps "Allow camera
22	 * access", never on mount.
23	 */
24	export function PhotoCapture({
25	  permission,
26	  photoUri,
27	  onRequestPermission,
28	  onOpenSettings,
29	  onCapture,
30	  onClear,
31	}: PhotoCaptureProps) {
32	  const cameraRef = useRef<CameraView>(null);
33	  // The uri of a photo whose `Image` reported it could not load — the OS can
34	  // reclaim a cached capture between writing it and this screen reading it
35	  // back. Tracked by value rather than a plain boolean so a freshly captured
36	  // photo (a new, different uri) is never mistaken for the one that failed.
37	  const [unavailableUri, setUnavailableUri] = useState<string | undefined>(
38	    undefined,
39	  );
40	  const isUnavailable = photoUri !== undefined && photoUri === unavailableUri;
41	
42	  async function capture() {
43	    const photo = await cameraRef.current?.takePictureAsync();
44	    if (photo?.uri) {
45	      onCapture(photo.uri);
46	    }
47	  }
48	
49	  if (photoUri && isUnavailable) {
50	    return (
51	      <View style={styles.container} testID="photo-unavailable">
52	        <Text style={styles.hint}>
53	          This photo is no longer available. Take a new one.
54	        </Text>
55	        <ActionButton
56	          label="Retake photo"
57	          kind="secondary"
58	          onPress={onClear}
59	          testID="retake-photo"
60	        />
61	      </View>
62	    );
63	  }
64	
65	  if (photoUri) {
66	    return (
67	      <View style={styles.container}>
68	        <Image
69	          source={{ uri: photoUri }}
70	          style={styles.preview}
71	          testID="photo-preview"
72	          onError={() => setUnavailableUri(photoUri)}
73	        />
74	        <ActionButton
75	          label="Remove photo"
76	          kind="secondary"
77	          onPress={onClear}
78	          testID="clear-photo"
79	        />
80	      </View>
81	    );
82	  }
83	
84	  if (permission === null) {
85	    return (
86	      <View style={styles.container} testID="photo-capture-loading">
87	        <Text style={styles.hint}>Checking camera access…</Text>
88	      </View>
89	    );
90	  }
91	
92	  if (permission.granted) {
93	    return (
94	      <View style={styles.container}>
95	        <CameraView ref={cameraRef} style={styles.camera} facing="back" />
96	        <ActionButton
97	          label="Take photo"
98	          onPress={capture}
99	          testID="capture-photo"
100	        />
101	      </View>
102	    );
103	  }
104	
105	  if (permission.canAskAgain) {
106	    return (
107	      <View style={styles.container}>
108	        <Text style={styles.hint}>Recall can attach a photo to this card.</Text>
109	        <ActionButton
110	          label="Allow camera access"
111	          onPress={onRequestPermission}
112	          testID="request-camera-permission"
113	        />
114	      </View>
115	    );
116	  }
117	
118	  return (
119	    <View style={styles.container}>
120	      <Text style={styles.hint}>
121	        Camera access is off. Turn it on in system settings to add a photo.
122	      </Text>
123	      <ActionButton
124	        label="Open settings"
125	        kind="secondary"
126	        onPress={onOpenSettings}
127	        testID="open-settings"
128	      />
129	    </View>
130	  );
131	}
132	
133	const styles = StyleSheet.create((theme) => ({
134	  container: {
135	    gap: theme.spacing(1.5),
136	  },
137	  camera: {
138	    height: theme.sizing.mediaHeight,
139	    borderRadius: theme.radius.md,
140	    overflow: "hidden",
141	  },
142	  preview: {
143	    height: theme.sizing.mediaHeight,
144	    borderRadius: theme.radius.md,
145	  },
146	  hint: {
147	    ...theme.typography.body,
148	    color: theme.colors.textMuted,
149	  },
150	}));
